#!/bin/bash
mkdir -p /opt/fleet/tune
if [ -f /opt/fleet/tune/tunealive.txt ]; then echo "SKIP already ran $(cat /opt/fleet/tune/tunealive.txt)"; exit 0; fi
base64 -d > /opt/fleet/tune/tuneall.sh <<'B64'

B64
chmod +x /opt/fleet/tune/tuneall.sh
date -u +%FT%TZ > /opt/fleet/tune/tunealive.txt
nohup setsid bash /opt/fleet/tune/tuneall.sh >/opt/fleet/tune/launch.out 2>&1 &
sleep 10
echo "TUNE LAUNCHED $(hostname) n=$(nvidia-smi -L|grep -c '^GPU ') ts=$(date -u +%FT%TZ)"
tail -5 /opt/fleet/tune/tune.log 2>/dev/null
